PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorName ?score
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
      ?investor wm:hasHolding ?ph .
      ?ph wm:currentValue ?cv .
      ?ph wm:cost ?cost .
      BIND(xsd:decimal(?cv) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall) WHERE {
      ?investor wm:hasInvestmentGoal ?ig .
      ?ig wm:shortfall ?shortfall .
    } GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?raAmt)) AS ?rebalanceAmt) WHERE {
      ?investor wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?raAmt .
    } GROUP BY ?investor
  }

  BIND (COALESCE(?netCashFlow, 0) + COALESCE(?holdingGain, 0) - COALESCE(?avgShortfall, 0) + COALESCE(?rebalanceAmt, 0) AS ?score)
}
ORDER BY DESC(?score)
