WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:hasCategory ?cat .
  OPTIONAL { ?cat rdfs:label ?categoryLabel . }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlow) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
