  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?scenarioChange) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?allocationPct)) AS ?allocationPct) (SUM(xsd:decimal(?totalInvestment)) AS ?sectorInvestment) WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct ;
          wm:totalInvestment ?totalInvestment .
    } GROUP BY ?investorId
  }
