PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel ?holdingGain ?rebalancingAmount ?scenarioChange ?cashFlowTotal WHERE {
  ?inv a wm:Investor .
  OPTIONAL {
    ?inv wm:hasRiskTolerance ?rt .
    ?rt rdfs:label ?riskToleranceLabel .
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?returnsPct)) AS ?holdingGain) WHERE {
      ?inv wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct .
    } GROUP BY ?inv
  }
  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?rebalancingAmount) WHERE {
      ?inv wm:hasRebalancingAction ?rebalance .
      ?rebalance wm:amount ?amount .
    } GROUP BY ?inv
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioChange) WHERE {
      ?inv wm:hasScenarioRebalancing ?scenario .
      ?scenario wm:newAllocationPct ?newAlloc .
      ?scenario wm:currentAllocationPct ?currAlloc .
    } GROUP BY ?inv
  }
  {
    SELECT ?inv (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowTotal) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?inv
  }
}
ORDER BY ?riskToleranceLabel

