SELECT ?metric ?count WHERE {
  {
    SELECT (COUNT(DISTINCT ?g) AS ?count) WHERE { ?g a wm:InvestmentGoal . }
    BIND("goalCount" AS ?metric)
  } UNION {
    SELECT (COUNT(DISTINCT ?h) AS ?count) WHERE { ?h a wm:PortfolioHolding . }
    BIND("holdingCount" AS ?metric)
  } UNION {
    SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE { ?c a wm:CashFlow . }
    BIND("transactionCount" AS ?metric)
  } UNION {
    SELECT (COUNT(DISTINCT ?r) AS ?count) WHERE { ?r a wm:RebalancingAction . }
    BIND("rebalanceCount" AS ?metric)
  } UNION {
    SELECT (COUNT(DISTINCT ?s) AS ?count) WHERE { ?s a wm:ScenarioRebalancing . }
    BIND("scenarioCount" AS ?metric)
  }
}

