    SELECT ?seg ?segmentLabel (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasSegment ?seg .
      ?seg rdfs:label ?segmentLabel .
      ?inv wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocPct .
    }
    GROUP BY ?seg ?segmentLabel
  }
  {
    SELECT ?seg (AVG(xsd:decimal(?returnPct)) AS ?avgReturnPct) (AVG(xsd:decimal(?currVal)) AS ?avgCurrentValue)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:hasSegment ?seg .
      ?inv wm:hasHolding ?hold .
      ?hold wm:returnsPct ?returnPct .
      ?hold wm:currentValue ?currVal .
    }
    GROUP BY ?seg
  }
}
ORDER BY ?segmentLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catLabel (SUM(?netCashFlow) AS ?totalNetCashFlow) (AVG(?goalProgress) AS ?avgGoalProgress) (SUM(?holdingGain) AS ?totalHoldingGain) (AVG(?riskScore) AS ?avgRiskScore) (AVG(?allocationPct) AS ?avgAllocationPct)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL {
    ?inv wm:hasCategory ?cat .
    OPTIONAL { ?cat rdfs:label ?catLabel . }
  }
  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    } GROUP BY ?inv
  }
  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?goalProgress) WHERE {
      ?inv wm:hasInvestmentGoal ?ig .
      ?ig wm:progressPct ?prog .
    } GROUP BY ?inv
  }
  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
      ?inv wm:hasHolding ?ph .
      ?ph wm:currentValue ?cv .
      ?ph wm:cost ?c .
      BIND (xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    } GROUP BY ?inv
  }
  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?rs)) AS ?riskScore) WHERE {
      ?inv wm:hasPortfolioHealth ?phh .
      ?phh wm:riskScore ?rs .
    } GROUP BY ?inv
  }
  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?alloc)) AS ?allocationPct) WHERE {
      ?inv wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?alloc .
    } GROUP BY ?inv
  }
}
GROUP BY ?catLabel
ORDER BY DESC(?totalNetCashFlow)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?categoryLabel ?sectorLabel ?investmentTypeLabel
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:hasCategory ?cat ;
           wm:hasSector ?sec ;
           wm:hasInvestmentType ?inv .
  ?cat rdfs:label ?categoryLabel .
  ?sec rdfs:label ?sectorLabel .
  ?inv rdfs:label ?investmentTypeLabel .
  FILTER NOT EXISTS { ?holding wm:returnsPct ?anyReturn . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentTypeLabel 
       (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue) 
       (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct) 
       (SUM(xsd:decimal(?dividends)) AS ?totalDividends)
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:hasInvestmentType ?invType ;
           wm:currentValue ?currentValue ;
           wm:returnsPct ?returnsPct ;
           wm:dividends ?dividends .
  ?invType rdfs:label ?investmentTypeLabel .
}
GROUP BY ?investmentTypeLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalCashFlow ?avgProgress
WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?progress)) AS ?avgProgress)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:progressPct ?progress ;
          wm:belongsToInvestor ?inv .
    }
    GROUP BY ?inv
    HAVING (AVG(xsd:decimal(?progress)) < 50)
  }
  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:cashFlowOfInvestor ?inv .
    }
    GROUP BY ?inv
  }
  ?inv wm:investorId ?investorId ;
       wm:investorName ?investorName .
}
ORDER BY DESC(?totalCashFlow)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?sharpe ?vol ?gain ?riskScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?inv (AVG(xsd:decimal(?sharpeRatio)) AS ?sharpe) (AVG(xsd:decimal(?volatility)) AS ?vol)
    WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:avgSharpeRatio ?sharpeRatio .
      ?goal wm:avgVolatilityPct ?volatility .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?gainVal)) AS ?gain)
    WHERE {
      ?inv wm:hasHolding ?holding .
      ?holding wm:currentValue ?curr .
      ?holding wm:cost ?cost .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gainVal)
    }
    GROUP BY ?inv
  }

  ?inv wm:hasPortfolioHealth ?health .
  ?health wm:riskScore ?riskScore .

  FILTER(?sharpe < 0 && ?vol > 20 && ?gain < 0 && ?riskScore > 50)
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .

  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50) .

  ?ph wm:liquidityScore ?liqScore .
  FILTER(xsd:decimal(?liqScore) < 30) .

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:returnsPct ?ret .
    FILTER(xsd:decimal(?ret) < 0)
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 20)
  }

  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    ?cf wm:type ?cfType .
    FILTER(CONTAINS(LCASE(STR(?cfType)), "withdrawal"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month ?triggeredAction (AVG(?avgAmt) AS ?avgActionAmount)
WHERE {
  {
    SELECT DISTINCT ?investorId ?month WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:date ?date .
      BIND(STR(?date) AS ?dateStr)
      BIND(SUBSTR(?dateStr,1,7) AS ?month)
    }
  }
  {
    SELECT DISTINCT ?investorId ?triggeredAction WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:triggeredAction ?triggeredAction .
    }
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?amount)) AS ?avgAmt) WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?month ?triggeredAction

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?progressPct) AS ?avgProgressPct)
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance ;
       wm:hasInvestmentGoal ?goal ;
       wm:hasPortfolioHealth ?ph .

  OPTIONAL { ?goal wm:progressPct ?progressPct . }
  OPTIONAL { ?ph wm:riskScore ?riskScore . }
  OPTIONAL { ?ph wm:liquidityScore ?liquidityScore . }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investor ?investorLabel
WHERE {
  ?investor a wm:Investor ;
            wm:riskTolerance ?rt ;
            rdfs:label ?investorLabel .
  FILTER(LCASE(STR(?rt)) = "aggressive")

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:shortfall ?sf .
  FILTER(xsd:decimal(?sf) > 0)

  ?hold a wm:PortfolioHolding ;
        wm:heldByInvestor ?investor ;
        wm:investmentName ?iname .
  FILTER(CONTAINS(LCASE(STR(?iname)), "gold"))

  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?rs .
  FILTER(xsd:decimal(?rs) > 60)

  ?sa a wm:SectorAllocation ;
      wm:allocationOfInvestor ?investor ;
      wm:allocationPct ?ap .
  FILTER(xsd:decimal(?ap) > 30)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?score WHERE {
  ?inv wm:investorName ?investorName .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?cash2025) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:date ?date ;
          wm:amount ?amt .
      FILTER(CONTAINS(LCASE(STR(?date)), "2025"))
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?rebAmt)) AS ?rebalanceAmt) WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?rebAmt .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?sf)) AS ?shortfallSum) WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?sf .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?allocChange) WHERE {
      ?inv wm:hasScenarioRebalancing ?sc .
      ?sc wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
    } GROUP BY ?inv
  }

  BIND( (COALESCE(?cash2025, 0) + COALESCE(?rebalanceAmt, 0) - COALESCE(?shortfallSum, 0) + COALESCE(?allocChange, 0)) AS ?score )
}
ORDER BY DESC(?score)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel ?avgHoldingGainPct ?totalRebalanceAmount ?avgScenarioChangePct ?totalCashFlow
WHERE {
  {
    SELECT ?cat (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingGainPct)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasHolding ?hold .
      ?hold wm:returnsPct ?returnsPct .
    }
    GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasRebalancingAction ?reb .
      ?reb wm:amount ?rebAmount .
    }
    GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChangePct)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasScenarioRebalancing ?sc .
      ?sc wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?curPct .
      BIND ((xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?scenarioChange)
    }
    GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?cat
  }
  ?cat rdfs:label ?categoryLabel .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?sr a wm:ScenarioRebalancing ;
      wm:scenario ?scenario ;
      wm:triggeredAction ?action ;
      wm:scenarioRebalancingOfInvestor ?inv .
  FILTER(CONTAINS(LCASE(STR(?scenario)), "market volatility"))
  FILTER(CONTAINS(LCASE(STR(?action)), "increase cash position"))
  ?inv wm:investorId ?investorId ;
      wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?avgReturnsPct) AS ?categoryAvgReturnsPct)
       (AVG(?avgSharpeRatio) AS ?categoryAvgSharpeRatio)
       (AVG(?riskScore) AS ?categoryAvgRiskScore)
WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?sharpe)) AS ?avgSharpeRatio)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:avgSharpeRatio ?sharpe .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?riskScore)) AS ?riskScore)
    WHERE {
      ?investor wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?investor
  }
  ?investor wm:category ?category .
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName ?riskScore
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasPortfolioHealth ?ph .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  ?ph wm:riskScore ?riskScore .
  FILTER ( xsd:decimal(?riskScore) > 100 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catLabel
       (COALESCE(?txCount, 0) AS ?transactionCount)
       (COALESCE(?holdCount, 0) AS ?holdingCount)
       (COALESCE(?goalCount, 0) AS ?goalCount)
       (COALESCE(?scenarioCount, 0) AS ?scenarioCount)
WHERE {
  {
    SELECT ?cat (COUNT(DISTINCT ?cf) AS ?txCount)
           (COUNT(DISTINCT ?ph) AS ?holdCount)
           (COUNT(DISTINCT ?goal) AS ?goalCount)
           (COUNT(DISTINCT ?sc) AS ?scenarioCount)
    WHERE {
      {
        SELECT ?cat ?cf WHERE {
          ?cf a wm:CashFlow .
          ?cf wm:cashFlowOfInvestor ?inv .
          ?inv wm:hasCategory ?cat .
        }
      }
      UNION
      {
        SELECT ?cat ?ph WHERE {
          ?ph a wm:PortfolioHolding .
          ?ph wm:heldByInvestor ?inv .
          ?inv wm:hasCategory ?cat .
        }
      }
      UNION
      {
        SELECT ?cat ?goal WHERE {
          ?goal a wm:InvestmentGoal .
          ?goal wm:belongsToInvestor ?inv .
          ?inv wm:hasCategory ?cat .
        }
      }
      UNION
      {
        SELECT ?cat ?sc WHERE {
          ?sc a wm:ScenarioRebalancing .
          ?sc wm:scenarioRebalancingOfInvestor ?inv .
          ?inv wm:hasCategory ?cat .
        }
      }
    }
    GROUP BY ?cat
  }
  OPTIONAL { ?cat rdfs:label ?catLabel . }
}
ORDER BY ?catLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalHoldingGain ?netCashFlow ?riskPressureScore WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .

  {
    SELECT ?inv (SUM(xsd:decimal(?cv) - xsd:decimal(?cost)) AS ?totalHoldingGain) WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:currentValue ?cv ;
            wm:cost ?cost .
    } GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    } GROUP BY ?inv
  }

  ?ph wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore ;
      wm:diversificationScore ?divScore .

  BIND ( xsd:decimal(?riskScore) + (100 - xsd:decimal(?liquidityScore)) + (100 - xsd:decimal(?divScore)) AS ?riskPressureScore)

  FILTER ( ?totalHoldingGain < 0 )
  FILTER ( ?netCashFlow < 0 )
  FILTER ( ?riskPressureScore > 180 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:investmentGoal ?gName .
    FILTER(CONTAINS(LCASE(STR(?gName)), "growth"))
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:sector ?holdSector .
    FILTER(CONTAINS(LCASE(STR(?holdSector)), "technology"))
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:sector ?allocSector .
    FILTER(CONTAINS(LCASE(STR(?allocSector)), "technology"))
  }

  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    ?cf wm:type ?cfType .
    FILTER(CONTAINS(LCASE(STR(?cfType)), "sip"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:hasCashFlowSource ?cfs .
      ?cfs rdfs:label ?cfsLabel .
      FILTER(CONTAINS(LCASE(STR(?cfsLabel)), "net banking"))
    }
  }
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasHolding ?hold .
      ?hold wm:hasSector ?holdSector .
      ?holdSector rdfs:label ?holdSectorLabel .
      FILTER(CONTAINS(LCASE(STR(?holdSectorLabel)), "corporate"))
    }
  }
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasSectorAllocation ?alloc .
      ?alloc wm:hasSector ?allocSector .
      ?allocSector rdfs:label ?allocSectorLabel .
      FILTER(CONTAINS(LCASE(STR(?allocSectorLabel)), "corporate"))
    }
  }
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv a wm:Investor .
  FILTER EXISTS {
    ?cf a wm:CashFlow ;
        wm:cashFlowOfInvestor ?inv ;
        wm:type ?cfType .
    FILTER(CONTAINS(LCASE(STR(?cfType)), "redemption"))
  }
  FILTER EXISTS {
    ?ra a wm:RebalancingAction ;
        wm:rebalancingActionOfInvestor ?inv ;
        wm:action ?raAction .
    FILTER(CONTAINS(LCASE(STR(?raAction)), "manual override"))
  }
  FILTER EXISTS {
    ?sr a wm:ScenarioRebalancing ;
        wm:scenarioRebalancingOfInvestor ?inv ;
        wm:scenario ?srScenario .
    FILTER(CONTAINS(LCASE(STR(?srScenario)), "flash crash"))
  }
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT DISTINCT ?investorId WHERE {
      ?inv1 a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasCashFlow ?cf .
      ?cf wm:type ?cfType .
      FILTER(CONTAINS(LCASE(STR(?cfType)), "withdrawal"))
    }
  }
  {
    SELECT DISTINCT ?investorId WHERE {
      ?inv2 a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasHolding ?hold .
      ?hold wm:returnsPct ?retPct .
      FILTER(xsd:decimal(?retPct) < 0)
    }
  }
  {
    SELECT DISTINCT ?investorId WHERE {
      ?inv3 a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocPct .
      FILTER(xsd:decimal(?allocPct) > 30)
    }
  }
  {
    SELECT DISTINCT ?investorId WHERE {
      ?inv4 a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasPortfolioHealth ?ph .
      ?ph wm:liquidityScore ?liqScore .
      FILTER(xsd:decimal(?liqScore) < 30)
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel ?categoryShortfall ?categoryHoldingValue ?categoryAvgAllocationPct ?categoryAvgLiquidity ?categoryAvgDiversification
WHERE {
  ?cat a wm:Category .
  OPTIONAL { ?cat rdfs:label ?categoryLabel . }

  OPTIONAL {
    SELECT ?cat (SUM(xsd:decimal(?sf)) AS ?categoryShortfall)
    WHERE {
      ?investor wm:hasCategory ?cat .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?sf .
    }
    GROUP BY ?cat
  }

  OPTIONAL {
    SELECT ?cat (SUM(xsd:decimal(?val)) AS ?categoryHoldingValue)
    WHERE {
      ?investor wm:hasCategory ?cat .
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?investor ;
          wm:currentValue ?val .
    }
    GROUP BY ?cat
  }

  OPTIONAL {
    SELECT ?cat (AVG(xsd:decimal(?alloc)) AS ?categoryAvgAllocationPct)
    WHERE {
      ?investor wm:hasCategory ?cat .
      ?allocRec a wm:SectorAllocation ;
                wm:allocationOfInvestor ?investor ;
                wm:allocationPct ?alloc .
    }
    GROUP BY ?cat
  }

  OPTIONAL {
    SELECT ?cat (AVG(xsd:decimal(?liq)) AS ?categoryAvgLiquidity) (AVG(xsd:decimal(?div)) AS ?categoryAvgDiversification)
    WHERE {
      ?investor wm:hasCategory ?cat .
      ?phl a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:liquidityScore ?liq ;
            wm:diversificationScore ?div .
    }
    GROUP BY ?cat
  }
}
ORDER BY ?categoryLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorId ?investorName ?sectorFocus WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  ?investor wm:sectorFocus ?sectorFocus .
  FILTER(CONTAINS(LCASE(STR(?sectorFocus)), "real estate"))
  FILTER NOT EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:hasSector ?sector .
    ?sector rdfs:label ?sectorLabel .
    FILTER(CONTAINS(LCASE(STR(?sectorLabel)), "real estate"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?depositTotal ?withdrawalTotal ?liquidityScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph ;
       wm:hasCashFlow ?cf .
  ?ph wm:liquidityScore ?liquidityScore .
  FILTER(xsd:decimal(?liquidityScore) < 30)

  {
    SELECT ?inv (SUM(IF(LCASE(STR(?type)) = "deposit", xsd:decimal(?value), 0)) AS ?depositTotal)
                 (SUM(IF(LCASE(STR(?type)) = "withdrawal", xsd:decimal(?value), 0)) AS ?withdrawalTotal)
    WHERE {
      ?inv wm:hasCashFlow ?c .
      ?c wm:type ?type ;
         wm:allowedValue ?value .
    }
    GROUP BY ?inv
  }

  FILTER(?depositTotal < ?withdrawalTotal)
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?totalCashFlow ?totalRebalancingAmount ?avgScenarioNewAllocationPct ?avgRiskScore ?avgGoalMatchPct
WHERE {
  {
    SELECT DISTINCT ?category WHERE {
      ?inv a wm:Investor ;
           wm:category ?category .
    }
  }
  OPTIONAL {
    SELECT ?category (SUM(xsd:decimal(?amt)) AS ?totalCashFlow)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:category ?category .
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amt .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (SUM(xsd:decimal(?raAmt)) AS ?totalRebalancingAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:category ?category .
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmt .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?newPct)) AS ?avgScenarioNewAllocationPct)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:category ?category .
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newPct .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?rs)) AS ?avgRiskScore) (AVG(xsd:decimal(?gm)) AS ?avgGoalMatchPct)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:category ?category .
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?rs ;
          wm:goalMatchPct ?gm .
    }
    GROUP BY ?category
  }
}
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?holdingGain) AS ?avgHoldingGain)
       (AVG(?allocConcentration) AS ?avgAllocationConcentration)
       (AVG(?rebalanceGap) AS ?avgRebalancingGap)
       (AVG(?scenarioChange) AS ?avgScenarioChange)
       (AVG(?goalVolatility) AS ?avgGoalVolatility)
WHERE {
  ?inv a wm:Investor ;
       wm:category ?category .

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?returnsPct)) AS ?holdingGain) WHERE {
      ?inv wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?allocationPct)) AS ?allocConcentration) WHERE {
      ?inv wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocationPct .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?gap)) AS ?rebalanceGap) WHERE {
      ?inv wm:hasRebalancingAction ?reb .
      ?reb wm:targetAllocationPct ?target .
      ?reb wm:currentAllocationPct ?current .
      BIND((xsd:decimal(?target) - xsd:decimal(?current)) AS ?gap)
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?change)) AS ?scenarioChange) WHERE {
      ?inv wm:hasScenarioRebalancing ?scen .
      ?scen wm:newAllocationPct ?new .
      ?scen wm:currentAllocationPct ?curr .
      BIND((xsd:decimal(?new) - xsd:decimal(?curr)) AS ?change)
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?volatility)) AS ?goalVolatility) WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:avgVolatilityPct ?volatility .
    } GROUP BY ?inv
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasPortfolioHealth ?health .
  ?goal wm:progressPct ?progressPct .
  ?health wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?progressPct) < 20) .
  FILTER(xsd:decimal(?riskScore) > 70)
}

PREFIX wm: <https://wealth.example.org/ontology/>
