SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
  FILTER NOT EXISTS { ?inv wm:category ?invCat . }
  ?inv wm:hasHolding ?holding .
  ?holding wm:category ?holdCat .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  FILTER EXISTS {
    SELECT ?inv WHERE {
      ?inv wm:hasHolding ?holding .
      ?holding wm:returnsPct ?ret .
      FILTER(?ret < 0)
    } LIMIT 1
  }

  FILTER EXISTS {
    SELECT ?inv WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?sf .
      FILTER(?sf > 1000000)
    } LIMIT 1
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?rebalanceId ?action ?month (COUNT(?cf) AS ?txCount)
WHERE {
  ?ra a wm:RebalancingAction ;
      wm:rebalanceId ?rebalanceId ;
      wm:action ?action ;
      wm:rebalancingActionOfInvestor ?inv .

  ?cf a wm:CashFlow ;
      wm:cashFlowOfInvestor ?inv ;
      wm:date ?date .

  BIND (SUBSTR(?date, 1, 7) AS ?month)
}
GROUP BY ?rebalanceId ?action ?month
ORDER BY ?rebalanceId ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName ?returnsPct ?dividends
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:returnsPct ?returnsPct ;
           wm:dividends ?dividends .
  OPTIONAL { ?holding wm:investmentName ?investmentName . }
  FILTER(?returnsPct < 0 && ?dividends > 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holding ?holdingId ?investmentName
WHERE {
  ?holding a wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }
  OPTIONAL { ?holding wm:investmentName ?investmentName . }
  FILTER NOT EXISTS { ?holding wm:sector ?sectorLiteral . }
  FILTER NOT EXISTS { ?holding wm:hasSector ?sectorObject . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (AVG(?invChange) AS ?avgChange) (SUM(?invChange) AS ?totalChange) (COUNT(?inv) AS ?recordCount)
WHERE {
  {
    SELECT ?inv ?timeHorizon (AVG(xsd:decimal(?new) - xsd:decimal(?curr)) AS ?invChange)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL { ?inv wm:timeHorizon ?timeHorizon . }
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:currentAllocationPct ?curr .
      ?sr wm:newAllocationPct ?new .
      FILTER (BOUND(?curr) && BOUND(?new))
    }
    GROUP BY ?inv ?timeHorizon
  }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?timeHorizon ?totalCashFlow ?avgGoalProgress ?avgHoldingReturn ?riskScore ?totalAllocationPct
WHERE {
  {
    SELECT DISTINCT ?investorId ?timeHorizon
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:timeToGoalMonths ?timeHorizon .
    }
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore)
    WHERE {
      ?phl a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?allocationPct)) AS ?totalAllocationPct)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
}
ORDER BY ?investorId ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?type ?label ?count WHERE {
  {
    SELECT ( "Logic" AS ?type ) ?logic ?logicLabel (COUNT(?ra) AS ?count)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:hasRebalancingLogic ?logic .
      OPTIONAL { ?logic rdfs:label ?logicLabel . }
    }
    GROUP BY ?logic ?logicLabel
  }
  UNION
  {
    SELECT ( "Scenario" AS ?type ) ?scenario ?scenarioLabel (COUNT(?sr) AS ?count)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:hasMarketScenario ?scenario .
      OPTIONAL { ?scenario rdfs:label ?scenarioLabel . }
    }
    GROUP BY ?scenario ?scenarioLabel
  }
  BIND(COALESCE(?logicLabel, ?scenarioLabel) AS ?label)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 100)

  ?sa a wm:SectorAllocation ;
      wm:allocationOfInvestor ?inv ;
      wm:allocationPct ?allocPct .
  FILTER(xsd:decimal(?allocPct) > 100)

  ?phold a wm:PortfolioHolding ;
        wm:heldByInvestor ?inv ;
        wm:returnsPct ?retPct .
  FILTER(xsd:decimal(?retPct) < 0)

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorId ?investorName WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  FILTER NOT EXISTS { ?investor wm:hasHolding ?holding . }
  FILTER NOT EXISTS { ?holding wm:heldByInvestor ?investor . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment ?totalCashFlow ?totalAllocationChange ?totalScenarioCount
WHERE {
  {
    SELECT ?segment (SUM(?amount) AS ?totalCashFlow)
    WHERE {
      ?inv a wm:Investor ;
           wm:segment ?segment ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?segment
  }
  {
    SELECT ?segment (SUM(?allocDiff) AS ?totalAllocationChange) (COUNT(?scenario) AS ?totalScenarioCount)
    WHERE {
      ?inv a wm:Investor ;
           wm:segment ?segment ;
           wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur ;
          wm:scenario ?scenario .
      BIND(?new - ?cur AS ?allocDiff)
    }
    GROUP BY ?segment
  }
}
